<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {api,post,type RecordRow,type ModuleSpec} from '../api'
import {loadAMap,type SDK,type MapView,type Overlay,type Polygon,type MouseTool,type Editor,type Point} from '../amap-sdk'
import {wgsToGcj,gcjToWgs} from '../amap-coordinates.mjs'
import Records from './Records.vue'
const props=defineProps<{spec:ModuleSpec;readonly?:boolean}>(),router=useRouter()
const el=ref<HTMLElement>(),title=ref('新地块'),saving=ref(false),loading=ref(false),error=ref(''),satellite=ref(false),mapRows=ref<RecordRow[]>([]),drawing=ref(false),selected=ref<RecordRow>(),address=ref(''),searching=ref(false),draftReady=ref(false)
let sdk:SDK|undefined,map:MapView|undefined,tool:MouseTool|undefined,editor:Editor|undefined,draft:Polygon|undefined,overlays:Overlay[]=[],disposed=false
type Geometry={type:'Polygon'|'MultiPolygon';coordinates:Point[][]|Point[][][]}
function cancel(){tool?.close(true);editor?.close();editor=undefined;if(draft)map?.remove(draft);draft=undefined;drawing.value=false;draftReady.value=false}
async function refresh(){try{const result=await api<{items:RecordRow[]}>('/records/lands?size=200');mapRows.value=result.items;if(selected.value)selected.value=result.items.find(r=>r.id===selected.value?.id);if(!sdk||!map)return;map.remove(overlays);overlays=[]
 for(const r of result.items){const geometry=r.data.geometry as Geometry|undefined
 if(geometry){const polygons=geometry.type==='Polygon'?[geometry.coordinates as Point[][]]:geometry.coordinates as Point[][][];for(const rings of polygons){const polygon=new sdk.Polygon({path:rings.map(ring=>ring.map(wgsToGcj)),strokeColor:'#246b47',strokeWeight:2,fillColor:'#52a56a',fillOpacity:0.25});polygon.on('click',()=>{selected.value=r});overlays.push(polygon)}}
 else if(typeof r.data.longitude==='number'&&typeof r.data.latitude==='number'){const marker=new sdk.Marker({position:wgsToGcj([r.data.longitude,r.data.latitude]),title:r.title});marker.on('click',()=>{selected.value=r});overlays.push(marker)}}
 map.add(overlays);if(overlays.length)map.setFitView(overlays,false,[60,60,60,60],17)
}catch(e){ElMessage.error((e as Error).message)}}
async function initialize(){loading.value=true;error.value='';try{sdk=await loadAMap();if(disposed||!el.value)return;map=new sdk.Map(el.value,{zoom:15,center:wgsToGcj([120.15,30.27]),viewMode:'2D',resizeEnable:true});map.addControl(new sdk.Scale());map.addControl(new sdk.ToolBar());if(!props.readonly){tool=new sdk.MouseTool(map);tool.on('draw',e=>{draft=e.obj;tool?.close(false);drawing.value=false;draftReady.value=true;ElMessage.success('边界绘制完成，可调整后保存')})}await refresh()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(initialize);onBeforeUnmount(()=>{disposed=true;editor?.close();tool?.close(true);map?.destroy()})
function toggleBase(){if(!sdk||!map)return;satellite.value=!satellite.value;map.setLayers(satellite.value?[new sdk.TileLayer.Satellite(),new sdk.TileLayer.RoadNet()]:[new sdk.TileLayer()])}
function begin(){if(!tool)return;cancel();tool.polygon({strokeColor:'#e79b30',fillColor:'#e79b30',fillOpacity:0.25});drawing.value=true;ElMessage.info('点击绘制边界，双击结束；新边界不会覆盖已有档案')}
function editDraft(){if(!sdk||!map||!draft)return;editor?.close();editor=new sdk.PolygonEditor(map,draft);editor.open();ElMessage.info('拖动边界点调整位置，保存时结束编辑')}
async function save(){if(!draft){ElMessage.warning('先绘制新地块边界');return}if(!title.value.trim()){ElMessage.warning('填写地块名称');return}editor?.close();const points=draft.getPath().map(p=>gcjToWgs([p.getLng(),p.getLat()]));if(points.length<3){ElMessage.warning('至少绘制三个边界点后再保存');return}const ring=[...points,points[0]];saving.value=true;try{const center:Point=[points.reduce((s,p)=>s+p[0],0)/points.length,points.reduce((s,p)=>s+p[1],0)/points.length];await post('/records/lands',{title:title.value,status:'已完成',data:{geometry:{type:'Polygon',coordinates:[ring]},longitude:center[0],latitude:center[1],note:'高德地图手绘，近似转换为 WGS84；面积仅供管理参考，非确权测绘成果'}});cancel();ElMessage.success('边界与定位已保存，后端已核算面积');await refresh()}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
async function search(){if(!sdk||!map||!address.value.trim())return;searching.value=true;const geocoder=new sdk.Geocoder();geocoder.getLocation(address.value,(status,result)=>{searching.value=false;if(disposed)return;const p=result.geocodes?.[0]?.location;if(status==='complete'&&p)map?.setZoomAndCenter(16,[p.getLng(),p.getLat()]);else ElMessage.warning('未找到位置，请填写完整省市乡镇或检查高德服务授权')})}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const form=new FormData();form.append('file',file);saving.value=true;try{const list=await api<{geometry:unknown;area:number}[]>('/gis/import',{method:'POST',body:form});for(let i=0;i<list.length;i++)await post('/records/lands',{title:`${file.name} 地块 ${i+1}`,status:'待核验',data:{geometry:list[i].geometry,measured_area:list[i].area,note:'文件导入 WGS84 边界；高德显示近似坐标转换，需人工核验'}});ElMessage.success(`已导入 ${list.length} 个地块`);await refresh()}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false;input.value=''}}
</script>
<template><div class="page-title"><div><h1>{{readonly?'辖区 GIS 一张图':'高德地块地图工作区'}}</h1><p>高德地图 · 地块边界 · 生产档案关联</p></div><el-button @click="refresh">刷新地块</el-button></div><section class="panel"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" @click="initialize">重试加载地图</el-button><div class="toolbar"><el-input v-model="address" placeholder="例如 浙江省杭州市余杭区" style="width:300px" @keyup.enter="search"/><el-button :loading="searching" :disabled="!map||!!error" @click="search">搜索定位</el-button><el-button :disabled="!map" @click="toggleBase">{{satellite?'切换标准地图':'切换卫星地图'}}</el-button></div><div v-if="!readonly" class="toolbar"><el-input v-model="title" placeholder="地块名称" style="width:180px"/><el-button :disabled="!map||drawing||saving" @click="begin">绘制新地块</el-button><el-button :disabled="!draftReady||saving" @click="editDraft">调整新边界</el-button><el-button type="primary" :disabled="!draftReady" :loading="saving" @click="save">保存新边界</el-button><el-button :disabled="!drawing&&!draftReady" @click="cancel">取消绘制</el-button><label class="muted">导入 GeoJSON / SHP ZIP <input type="file" accept=".json,.geojson,.zip" :disabled="saving" @change="importFile" style="max-width:190px"/></label></div><div ref="el" v-loading="loading" class="map" aria-label="高德农业地块地图"></div><p class="muted">点击边界或定位标记查看档案。初始中心为杭州演示位置，地图需联网。SHP ZIP 须含 shp/shx/dbf/prj；坐标转换与面积仅供管理参考。</p><div v-if="selected" class="map-detail"><h3>{{selected.title}}</h3><p>作物：{{selected.data.crop||'未填写'}} · 测算面积：{{selected.data.measured_area||'未测算'}} 亩 · {{selected.demo?'演示记录':'用户录入'}}</p><el-button v-if="!readonly" type="primary" @click="router.push({path:'/workspace/planting-flow',query:{plot_id:selected.id}})">进入种植管理流程</el-button><el-button @click="selected=undefined">关闭详情</el-button></div><div class="tags"><el-tag v-for="r in mapRows" :key="r.id" @click="selected=r" style="cursor:pointer">{{r.title}}</el-tag></div></section><Records v-if="!readonly" :key="mapRows.length" :spec="spec"/></template>
<style scoped>.map-detail{padding:16px;margin-bottom:16px;background:#f1f7f1;border-radius:12px}.toolbar{flex-wrap:wrap;margin-bottom:14px}</style>



